%% Deterministic full-variant sample values, keyed by mcp:fieldType:
%% string -> <<"sample_" field_name>>, datetime -> <<"2026-08-29T12:00:00Z">>,
%% integer -> 42, float -> 3.5, boolean -> true, atom -> sample_atom,
%% list_string -> [<<"alpha">>, <<"beta">>], map -> #{<<"k">> => <<"v">>}.
%% JSON keys on the wire side are the field's mcp:wireName (falls back to
%% mcp:fieldName when absent) -- see beam4pm_mcp_contracts_codec.erl.

mcp_resource_map_roundtrip_test() ->
    {ok, Rec} = beam4pm_mcp_contracts:new_mcp_resource(#{
        uri => <<"sample_uri">>,
        name => <<"sample_name">>,
        title => <<"sample_title">>,
        description => <<"sample_description">>,
        mime_type => <<"sample_mime_type">>,
        size => 42
    }),
    Map = beam4pm_mcp_contracts_codec:to_map(Rec),
    ?assertEqual(<<"sample_uri">>, maps:get(<<"uri">>, Map)),
    ?assertEqual(<<"sample_name">>, maps:get(<<"name">>, Map)),
    ?assertEqual(<<"sample_title">>, maps:get(<<"title">>, Map)),
    ?assertEqual(<<"sample_description">>, maps:get(<<"description">>, Map)),
    ?assertEqual(<<"sample_mime_type">>, maps:get(<<"mimeType">>, Map)),
    ?assertEqual(42, maps:get(<<"size">>, Map)),
    {ok, Rec2} = beam4pm_mcp_contracts_codec:from_map(mcp_resource,
        Map#{<<"totally_unknown_key_zz">> => <<"dropped">>}),
    ?assertEqual(Rec, Rec2).

